 c.fillStyle=cloth;c.beginPath();c.moveTo(cx-245,640);c.bezierCurveTo(cx-220,478,cx-127,458,cx-57,470);c.lineTo(cx+57,470);c.bezierCurveTo(cx+157,468,cx+224,512,cx+249,640);c.closePath();c.fill();if(look===1){c.strokeStyle='#3f453f';c.lineWidth=4;c.stroke()}c.fillStyle=skin;c.beginPath();c.roundRect(cx-39,385,78,130,26);c.fill();hairShape();c.fillStyle=hair;c.fill();c.fillStyle=skin;c.beginPath();c.ellipse(cx,283,rx,ry,(variation%3-1)*.03,0,Math.PI*2);c.fill();if(look===1){c.strokeStyle='#343b36';c.lineWidth=3;c.stroke()}
